using MediatR; using OrderingService.Application.Abstractions; using OrderingService.Application.IntegrationEvents; using OrderingService.Application.Outbox; using OrderingService.Domain.Fulfillment; using OrderingService.Domain.Orders;
namespace OrderingService.Application.Fulfillment;
public sealed class DispatchShipmentHandler(IOrderingUnitOfWork unitOfWork,IOrderRepository orders,IShipmentRepository shipments, IOutboxRepository outbox):IRequestHandler<DispatchShipmentCommand,ShipmentDto?>
{ public Task<ShipmentDto?> Handle(DispatchShipmentCommand r,CancellationToken ct)=>unitOfWork.ExecuteAsync(async tx=>{var shipment=await shipments.GetByOrderIdAsync(r.OrderId,tx,ct);if(shipment is null)return null;if(shipment.Status==ShipmentStatus.Shipped)return ShipmentMapper.ToDto(shipment);var order=await orders.GetByIdAsync(r.OrderId,tx,ct)??throw new InvalidOperationException("Shipment order is missing.");var prior=shipment.Status;shipment.Dispatch(r.Carrier,r.TrackingNumber,DateTime.UtcNow);if(!order.MoveToFulfillmentStatus(OrderStatus.Shipped))throw new InvalidOperationException("Order could not be marked shipped.");if(!await shipments.UpdateAsync(shipment,prior,tx,ct)||!await orders.TryUpdateStatusAsync(order.Id,order.Status,[OrderStatus.Confirmed],tx,ct))throw new InvalidOperationException("Shipment changed before dispatch.");await outbox.AddAsync(OutboxMessageFactory.Create(OrderIntegrationEventFactory.CreateOrderStatusChanged(order, OrderStatus.Confirmed)),tx,ct); await outbox.AddAsync(OutboxMessageFactory.CreateKafka(OrderIntegrationEventFactory.CreateOrderProjectionStatusChanged(order, OrderStatus.Confirmed)),tx,ct); await shipments.AddHistoryAsync(ShipmentStatusHistory.Create(shipment.Id,prior,shipment.Status,r.ActorId,"Shipment dispatched.",DateTime.UtcNow),tx,ct);return ShipmentMapper.ToDto(shipment);},ct); }